def numEnclaves(grid):
    # Helper DFS (explicit stack, avoids recursion limits) to flood-fill from a given cell
    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            x, y = stack.pop()
            # Out of bounds or not land, skip
            if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] != 1:
                continue
            grid[x][y] = 0  # Mark as visited by setting to sea
            # Visit all adjacent
            stack.extend([(x+1, y), (x-1, y), (x, y+1), (x, y-1)])

    rows, cols = len(grid), len(grid[0])

    # 1. Remove all land cells connected to borders
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 1:
                dfs(r, c)
    for c in range(cols):
        for r in [0, rows-1]:
            if grid[r][c] == 1:
                dfs(r, c)

    # 2. Count remaining land cells (enclaves)
    result = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                result += 1
    return result
